var e={cards:[{type:`demo/plan-status`,appliesTo:e=>e.references.some(e=>e.kind===`plan`),mount(e,t){e.className=`demo-plugin-card`;let n=t=>{let n=t.references.filter(e=>e.kind===`plan`).length;e.textContent=`Plan linked · ${t.status} · ${n} reference${n===1?``:`s`}`};return n(t.task),e.addEventListener(`dblclick`,t.refresh),{update:n,destroy(){e.replaceChildren()}}}}],referenceResolvers:[{id:`demo/plan`,pattern:`^https://plans\\.myslop\\.app/p/`,kinds:[`plan`],resolve(e){let t=e.url.split(`/`).filter(Boolean).at(-1)||``;return{label:e.title||`Implementation plan`,icon:`plan`,meta:{provider:`myslop plans`,id:t}}}}]};export{e as demoPluginUI};